/* One immutable location for every first-party runtime asset. */
(() => {
  'use strict';
  if (window.TDBRelease) return;
  const entry = document.currentScript;
  if (!entry?.src) throw Error('TDB startup must be loaded from an external script');
  const base = new URL('./', entry.src).href;
  const commit = entry.src.match(/tdb-webflow-runtime@([a-f0-9]{40})\//)?.[1] || null;
  window.TDBRelease = Object.freeze({
    version: '2.0.0',
    commit,
    base,
    asset: (filename) => new URL(filename, base).href,
  });
})();

/* TDB motion policy v1.0.0. Owner-approved full motion for design review.
 * Inline the minified artifact at the start of the Webflow site head. This
 * small policy does not fetch or eagerly initialize the shared motion module.
 * It changes TDB's behavior only; the browser's media queries remain intact.
 */
(() => {
  'use strict';
  if (window.TDBMotionPolicy) return;
  const reduced = Object.freeze({
    matches: false,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
  });
  window.TDBMotionPolicy = Object.freeze({ version: '1.0.0', mode: 'full', reduced });
  document.documentElement.dataset.tdbMotion = 'full';
})();

/* One immutable motion profile, installed by the existing startup entry.
 * config/motion.json also generates the CSS tokens. No requests, observers,
 * computed-style reads or additional animation loop are needed here.
 */
(() => {
  'use strict';
  if (window.TDBMotionProfile) return;
  const config = {
    pace: 1.25,
    character: 'soft',
    families: {
      navigation: { pace: 1, character: 'current' },
      accordion: { pace: 1, character: 'current' },
      fade: { pace: 1, character: 'current' },
    },
    distance: { base: 400, reference: 375, desktopBreakpoint: 992, desktopMin: 650, maximum: 950 },
    physics: { coast: 4.2, edgeSpring: 14, marqueeDesktop: 40, marqueeMobile: 22 },
    characters: {
      current: {},
      soft: {
        travel: 'cubic-bezier(.45,0,.25,1)',
        panel: 'cubic-bezier(.4,0,.2,1)',
        release: 'cubic-bezier(.25,.55,.3,1)',
        fade: 'ease-in-out',
        control: 'cubic-bezier(.4,0,.2,1)',
      },
    },
  };
  const { distance } = config;
  const physics = Object.freeze(config.physics);
  function createProfile({ pace, character }) {
    const curves = Object.freeze(config.characters[character]);
    const time = (milliseconds) => Math.round(milliseconds * pace);
    const easing = (role, original) => curves[role] || original;
    // Clamp distance before applying this family's independent pace.
    const horizontal = (width = innerWidth) =>
      time(
        matchMedia('(min-width:' + distance.desktopBreakpoint + 'px)').matches
          ? Math.round(
              Math.min(
                distance.maximum,
                Math.max(
                  distance.desktopMin,
                  distance.base * Math.sqrt(width / distance.reference),
                ),
              ),
            )
          : distance.base,
      );
    const vertical = (
      height = document.documentElement.clientHeight || innerHeight || distance.reference,
    ) =>
      time(
        Math.round(
          Math.min(
            distance.maximum,
            Math.max(distance.base, distance.base * Math.sqrt(height / distance.reference)),
          ),
        ),
      );
    return Object.freeze({
      pace,
      character,
      time,
      easing,
      horizontal,
      vertical,
      physics,
      elapsed: (milliseconds) => milliseconds / pace,
    });
  }
  const content = createProfile(config);
  const families = Object.freeze(
    Object.fromEntries(
      Object.entries(config.families || {}).map(([name, settings]) => [
        name,
        createProfile(settings),
      ]),
    ),
  );
  const forFamily = (name) => families[name] || content;
  // Set the same generated tokens once at startup, so deferred CSS and early JS
  // cannot briefly use different profiles. There are no layout reads here.
  const rootStyle = document.documentElement.style;
  rootStyle.setProperty('--tdb-motion-pace', String(content.pace));
  for (const [role, curve] of Object.entries(config.characters[content.character]))
    if (role !== 'fade' || !families.fade)
      rootStyle.setProperty('--tdb-motion-ease-' + role, curve);
  for (const name of ['navigation', 'accordion', 'fade']) {
    const family = forFamily(name);
    rootStyle.setProperty('--tdb-' + name + '-pace', String(family.pace));
    for (const role of ['travel', 'panel', 'release', 'fade', 'control'])
      rootStyle.setProperty('--tdb-' + name + '-ease-' + role, family.easing(role, 'initial'));
  }
  if (families.fade)
    rootStyle.setProperty('--tdb-motion-ease-fade', families.fade.easing('fade', 'initial'));
  window.TDBMotionProfile = Object.freeze({
    version: '1.1.0',
    ...content,
    easing: (role, original) =>
      (role === 'fade' ? forFamily('fade') : content).easing(role, original),
    families,
    forFamily,
  });
})();

/* TDB shared dependency registry v2.0.0. One release root and one flight per asset. */
(() => {
  'use strict';
  if (window.TDBModules) return;
  const flights = new Map();
  const registry = document.currentScript;
  const failedNodes = new WeakSet();
  const owner = registry?.src
    ? registry
    : document.querySelector('script[data-tdb-reviews-loader][src]') ||
      document.querySelector('script[data-tdb-logo-marquee-loader][src]');
  const releaseRoot =
    window.TDBRelease?.base || (owner?.src ? new URL('./', owner.src).href : null);
  function resolve(url) {
    const requested = new URL(url, location.href);
    const firstParty =
      requested.origin === 'https://cdn.jsdelivr.net' &&
      requested.pathname.match(
        /^\/gh\/TheDentalBarns\/tdb-webflow-(?:runtime|attribution)@[^/]+\/dist\/([^/]+)$/,
      );
    return releaseRoot && firstParty ? new URL(firstParty[1], releaseRoot).href : requested.href;
  }
  function dependencyError(code, message) {
    return Object.assign(new Error(message), { code });
  }
  // A timeout does not cancel script execution. Keep the original transport until
  // it settles; only an explicit network error permits another execution attempt.
  function load(url, { attribute, ready, type = 'script', timeout = 20000 } = {}) {
    if (!['script', 'module', 'style'].includes(type))
      return Promise.reject(Error('Unknown dependency type: ' + type));
    const src = resolve(url),
      key = type + ':' + src;
    if (/\/tdb-swiper-8\.4\.7\.min\.js$/.test(src) && ready) {
      const engineReady = ready;
      ready = () =>
        engineReady() &&
        (registry?.src
          ? typeof window.TDBSwiper?.create === 'function'
          : Boolean(window.TDBSwiper));
    }
    try {
      if (ready?.()) return Promise.resolve();
    } catch (error) {
      return Promise.reject(error);
    }
    const previous = flights.get(key);
    if (previous) {
      if (ready && previous.complete) {
        // The tag loaded earlier, but this caller's required export is absent.
        // Do not turn a fulfilled transport promise into false readiness.
        return Promise.reject(
          dependencyError('TDB_EXPORT', 'Dependency loaded without expected export: ' + src),
        );
      }
      if (ready) previous.checks.add(ready);
      return previous.promise;
    }
    const style = type === 'style';
    const candidates = style
      ? [...document.querySelectorAll('link[rel="stylesheet"]')]
      : [...document.scripts];
    const address = (node) => (style ? node.href : node.src);
    let node =
      candidates.find((n) => !failedNodes.has(n) && address(n) === src) ||
      (attribute && document.querySelector(`${style ? 'link' : 'script'}[${attribute}]`));
    if (node && failedNodes.has(node)) node = null;
    if (node && address(node) !== src)
      return Promise.reject(Error('Conflicting dependency URL: ' + attribute));
    if (node && !style && (node.type === 'module') !== (type === 'module'))
      return Promise.reject(Error('Conflicting dependency type: ' + src));
    const fresh = !node;
    node ||= document.createElement(style ? 'link' : 'script');
    let fulfill,
      reject,
      timer,
      readyFrame = null,
      recheckedStyle = false,
      settled = false,
      timedOut = false;
    const promise = new Promise((a, b) => {
      fulfill = a;
      reject = b;
    });
    const entry = { promise, checks: new Set(ready ? [ready] : []), complete: false };
    flights.set(key, entry);
    function cleanup() {
      clearTimeout(timer);
      if (readyFrame !== null) cancelAnimationFrame(readyFrame);
      node.removeEventListener('load', done);
      node.removeEventListener('error', fail);
    }
    function invalidate() {
      failedNodes.add(node);
      if (fresh) node.remove();
      if (flights.get(key) === entry) flights.delete(key);
    }
    function fail(error) {
      if (settled) return;
      settled = true;
      cleanup();
      invalidate();
      reject(dependencyError('TDB_NETWORK', 'Dependency unavailable: ' + src));
    }
    function done() {
      if (settled || readyFrame !== null) return;
      try {
        for (const check of entry.checks)
          if (!check())
            throw dependencyError(
              'TDB_EXPORT',
              'Dependency loaded without expected export: ' + src,
            );
      } catch (error) {
        // Match the feature CSS gate: WebKit may expose a loaded stylesheet's
        // computed readiness flag only after the next style application frame.
        if (style && !recheckedStyle) {
          recheckedStyle = true;
          readyFrame = requestAnimationFrame(() => {
            readyFrame = null;
            done();
          });
          return;
        }
        settled = true;
        cleanup();
        entry.checks.clear();
        // The code already ran. Retain a terminal failure, not a retryable URL.
        const failure = dependencyError(
          'TDB_EXPORT',
          'Dependency loaded without expected export: ' + src,
        );
        entry.promise = Promise.reject(failure);
        entry.promise.catch(() => {});
        reject(failure);
        return;
      }
      settled = true;
      cleanup();
      entry.checks.clear();
      entry.complete = true;
      node.dataset.tdbLoaded = 'true';
      if (timedOut) entry.promise = Promise.resolve();
      fulfill();
    }
    // Keep rejected shared flights handled even when an abandoned consumer stops
    // listening; each consumer still receives the original rejected promise.
    promise.catch(() => {});
    if (node.dataset.tdbLoaded === 'true' || (style && node.sheet)) {
      done();
      return promise;
    }
    node.addEventListener('load', done, { once: true });
    node.addEventListener('error', fail, { once: true });
    timer = setTimeout(
      () => {
        timedOut = true;
        // Keep the listeners to adopt a late successful load or release an
        // explicit late network failure. Callers still receive the timeout now.
        reject(dependencyError('TDB_TIMEOUT', 'Dependency timed out: ' + src));
      },
      Number.isFinite(timeout) && timeout > 0 ? timeout : 20000,
    );
    if (fresh) {
      if (style) {
        node.rel = 'stylesheet';
        node.href = src;
      } else {
        node.src = src;
        node.async = true;
        if (type === 'module') node.type = 'module';
      }
      if (attribute) node.setAttribute(attribute, 'true');
      document.head.append(node);
    }
    return promise;
  }
  function loadWithRecovery(url, options = {}) {
    return load(url, options).catch((error) => {
      if (error.code !== 'TDB_NETWORK') throw error;
      return new Promise((resolve) => setTimeout(resolve, 250)).then(() => load(url, options));
    });
  }
  const busy = new WeakMap();
  async function withBusy(trigger, action, { signal, loading = true, onStart, onError } = {}) {
    if (signal?.aborted || trigger.getAttribute('aria-busy') === 'true') return;
    const token = {};
    busy.set(trigger, token);
    trigger.setAttribute('aria-busy', 'true');
    if (loading) trigger.setAttribute('data-tdb-loading', 'true');
    const clear = () => {
      if (busy.get(trigger) !== token) return;
      busy.delete(trigger);
      trigger.removeAttribute('aria-busy');
      if (loading) trigger.removeAttribute('data-tdb-loading');
    };
    signal?.addEventListener('abort', clear, { once: true });
    try {
      onStart?.();
      return await action();
    } catch (error) {
      if (!signal?.aborted && error.name !== 'AbortError') {
        if (onError) onError(error);
        else throw error;
      }
    } finally {
      signal?.removeEventListener('abort', clear);
      clear();
    }
  }
  window.TDBModules = Object.freeze({
    version: '2.0.0',
    load,
    loadWithRecovery,
    resolve,
    withBusy,
  });
})();

/* Capture holds early; runtime permission gates controller/audio requests. */
function prepareHoldAudioLoader(deferred) {
  'use strict';
  const buttons = [...document.querySelectorAll('[data-tdb-hold-audio]')];
  if (window.TDBHoldAudioLoader || !buttons.length) return;
  const lifecycle = new AbortController(),
    options = { signal: lifecycle.signal };
  let flight,
    observer,
    held,
    context,
    enable,
    disposed = false;
  const permission = deferred ? new Promise((resolve) => (enable = resolve)) : Promise.resolve();
  function audioContext() {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    return (context ||= new AudioContext());
  }
  function clearHint(session) {
    const hint = session.hint;
    if (!hint) return;
    if (hint.element) {
      hint.element.textContent = hint.text;
      for (const property of ['opacity', 'visibility']) {
        if (hint[property]) hint.element.style.setProperty(property, hint[property]);
        else hint.element.style.removeProperty(property);
      }
    }
    session.hint = null;
    if (session.button.getAttribute('aria-description') === hint.message)
      session.button.removeAttribute('aria-description');
    if (session.button.title === hint.message) session.button.title = 'Hold to listen';
  }
  function stopPreparing(session) {
    clearTimeout(session.hintTimer);
    context?.removeEventListener?.('statechange', session.deviceChanged);
    clearHint(session);
  }
  function watchDevice(session) {
    session.deviceChanged = () => {
      if (held !== session || context.state !== 'running' || !session.hint) return;
      clearHint(session);
      session.button.setAttribute('aria-busy', 'true');
      session.button.setAttribute('data-tdb-loading', 'true');
    };
    context.addEventListener?.('statechange', session.deviceChanged);
    session.hintTimer = setTimeout(() => {
      // A first touch-down may not grant playback until touch-up. This is not
      // a download: don't leave an impossible-to-complete hold spinning.
      if (
        held !== session ||
        context.state !== 'suspended' ||
        !['touch', 'pen'].includes(session.pointerType) ||
        navigator.userActivation?.hasBeenActive
      )
        return;
      const message = 'Tap once, then hold';
      const element = session.button
        .closest('[data-tdb-audio-card]')
        ?.querySelector('[data-tdb-audio-words]');
      session.hint = {
        message,
        element,
        text: element?.textContent,
        opacity: element?.style.opacity,
        visibility: element?.style.visibility,
      };
      if (element) {
        element.textContent = message;
        element.style.visibility = 'visible';
        element.style.opacity = '1';
      }
      session.button.removeAttribute('aria-busy');
      session.button.removeAttribute('data-tdb-loading');
      session.button.title = message;
      session.button.setAttribute('aria-description', message);
    }, 250);
  }
  function load() {
    if (!flight) {
      flight = permission
        .then(() => {
          if (disposed) return;
          return window.TDBModules.load(
            window.TDBRelease?.asset('tdb-hold-audio.js') ||
              new URL('tdb-hold-audio.js', window.TDBRuntimeModuleRoot).href,
            { ready: () => typeof window.TDBHoldAudio?.press === 'function' },
          );
        })
        .then(() => {
          observer?.disconnect();
        })
        .catch((error) => {
          flight = null;
          throw error;
        });
    }
    return flight;
  }
  function release(immediate = false) {
    const session = held;
    held = null;
    window.TDBHoldAudio?.release(immediate);
    if (!session) return;
    stopPreparing(session);
    clearTimeout(session.timeout);
    session.button.setAttribute('aria-pressed', 'false');
    session.button.removeAttribute('aria-busy');
    session.button.removeAttribute('data-tdb-loading');
    if (session.pointer != null && session.button.hasPointerCapture?.(session.pointer))
      session.button.releasePointerCapture(session.pointer);
  }
  function press(button, input) {
    if (disposed || held?.button === button || button.disabled) return;
    release();
    const session = { button, ...input };
    held = session;
    button.setAttribute('aria-pressed', 'true');
    button.setAttribute('aria-busy', 'true');
    button.setAttribute('data-tdb-loading', 'true');
    const failed = () => {
      if (held !== session) return;
      release();
      button.title = 'Sound unavailable. Tap once, then hold to try again.';
      button.setAttribute('aria-description', button.title);
    };
    // Bound consent/module/device waits as well as the controller's audio wait.
    session.timeout = setTimeout(failed, 30000);
    if (session.pointer != null) {
      try {
        button.setPointerCapture(session.pointer);
      } catch (_) {}
    }
    try {
      // Unlock synchronously even when a cold module download is still pending.
      const resumed = audioContext().resume();
      watchDevice(session);
      resumed.then(session.deviceChanged, failed);
      // Hand off the original held input while permission is pending so the
      // controller can download audio; playback and visuals wait for readiness.
      load()
        .then(async () => {
          if (!disposed && held === session && button.isConnected && !document.hidden)
            await window.TDBHoldAudio.press(button, input, context, resumed);
          if (held === session) {
            clearTimeout(session.timeout);
            stopPreparing(session);
          }
        })
        .catch(failed);
    } catch (_) {
      failed();
    }
  }
  for (const button of buttons) {
    button.addEventListener(
      'pointerdown',
      (event) => {
        if (event.button === 0 && event.isPrimary !== false)
          press(button, { pointer: event.pointerId, pointerType: event.pointerType });
      },
      options,
    );
    button.addEventListener(
      'keydown',
      (event) => {
        if (event.key === 'Escape') return release();
        if (![' ', 'Enter'].includes(event.key)) return;
        event.preventDefault();
        if (!event.repeat) press(button, { key: event.key });
      },
      options,
    );
    button.addEventListener(
      'keyup',
      (event) => {
        if (held?.button === button && held.key === event.key) {
          event.preventDefault();
          release();
        }
      },
      options,
    );
    button.addEventListener(
      'blur',
      () => {
        if (held?.button === button) release();
      },
      options,
    );
    button.addEventListener(
      'lostpointercapture',
      (event) => {
        if (held?.button === button && held.pointer === event.pointerId) release();
      },
      options,
    );
    for (const type of ['click', 'contextmenu'])
      button.addEventListener(type, (event) => event.preventDefault(), options);
    button.addEventListener('focus', () => load().catch(() => {}), options);
  }
  function unlock() {
    // Prepare the shared device on an earlier tap (including consent), rather
    // than discarding that activation because no speaker has been held yet.
    // No module, sound request or source is started by this preparation.
    if (disposed || navigator.userActivation?.hasBeenActive === false) return;
    try {
      audioContext();
      if (context.state !== 'running' && context.state !== 'closed')
        context.resume().catch(() => {});
    } catch (_) {}
  }
  for (const type of ['pointerup', 'touchend', 'mousedown', 'keydown'])
    window.addEventListener(type, unlock, { ...options, capture: true, passive: true });
  for (const type of ['pointerup', 'pointercancel'])
    window.addEventListener(
      type,
      (event) => {
        if (held && held.pointer === event.pointerId) release();
      },
      options,
    );
  window.addEventListener('blur', () => release(), options);
  window.addEventListener('pagehide', () => release(true), options);
  document.addEventListener(
    'visibilitychange',
    () => {
      if (document.hidden) release(true);
    },
    options,
  );
  function observe() {
    if (window.IntersectionObserver) {
      observer = new IntersectionObserver(
        (entries) => {
          if (entries.some((entry) => entry.isIntersecting)) load().catch(() => {});
        },
        { rootMargin: '600px 0px' },
      );
      buttons.forEach((button) => observer.observe(button.closest('[data-tdb-audio-card]')));
    } else load().catch(() => {});
  }
  if (!deferred) observe();
  window.TDBHoldAudioLoader = Object.freeze({
    start() {
      if (!enable || disposed) return;
      enable();
      enable = null;
      observe();
    },
    destroy() {
      release(true);
      disposed = true;
      lifecycle.abort();
      enable?.();
      enable = null;
      observer?.disconnect();
      window.TDBHoldAudio?.destroy();
      if (context && context.state !== 'closed') context.close().catch(() => {});
    },
  });
}

/* Remember native summary exposure before consent/deferred review preparation.
 * Observation only: no content changes, network work or motion in startup. */
(() => {
  'use strict';
  if (window.TDBReviewSummaryVisibility) return;
  const seen = new WeakMap(),
    pending = new Set();
  let observer;
  const belowViewport = (card) => {
    const rect = card.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0 && rect.top >= innerHeight;
  };
  function release(card) {
    seen.set(card, true);
    pending.delete(card);
    observer?.unobserve(card);
    if (!pending.size) observer?.disconnect();
  }
  function record(entries) {
    if (document.hidden) return;
    for (const entry of entries) if (entry.isIntersecting) release(entry.target);
  }
  function start() {
    if (!('IntersectionObserver' in window)) return;
    const cards = document.querySelectorAll(
      '[data-tdb-review-introduction] [data-tdb-review-summary]',
    );
    if (!cards.length) return;
    observer = new IntersectionObserver(record, { threshold: 0 });
    for (const card of cards) {
      // A restored/scrolled page has uncertain earlier exposure: keep its totals.
      const exposed = scrollY > 0 || !belowViewport(card);
      seen.set(card, exposed);
      if (!exposed) {
        pending.add(card);
        observer.observe(card);
      }
    }
  }
  window.TDBReviewSummaryVisibility = Object.freeze({
    claim(card) {
      if (!card) return false;
      record(observer?.takeRecords() || []);
      const unseen = seen.get(card) === false && belowViewport(card);
      release(card);
      return unseen;
    },
  });
  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', start, { once: true });
  else start();
})();

/* The only Webflow JS entry. Start essential foundation as soon as the DOM is ready.
 * Consent releases runtime; runtime owns the existing proximity/intent gates. */
(() => {
  'use strict';
  if (window.TDBStart) return;
  let state = 'waiting',
    error = null;
  let complete;
  const ready = new Promise((resolve) => {
    complete = resolve;
  });
  window.TDBStart = Object.freeze({ ready, status: () => ({ state, error }) });
  function load() {
    if (state !== 'waiting') return;
    state = 'loading';
    window.TDBModules.loadWithRecovery(window.TDBRelease.asset('tdb-foundation.js'), {
      attribute: 'data-tdb-foundation-js',
      ready: () => Boolean(window.TDBConsent && window.TDBNavbarState),
    }).then(
      () => {
        state = 'ready';
        complete(true);
      },
      (failure) => {
        state = 'failed';
        error = failure.code || failure.message;
        console.warn('TDB startup unavailable.', failure);
        complete(false);
      },
    );
  }
  function start() {
    document.body.setAttribute('data-wf-scroll-motion', 'none');
    // Capture a held press before foundation/runtime downloads or idle startup.
    // Controller/audio fetching still waits for the consent-released runtime.
    prepareHoldAudioLoader(true);
    load();
  }
  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', start, { once: true });
  else start();
})();
